const std = @import("std");

fn update(bit: []i32, idx: usize, delta: i32) void {
    var i = idx;
    while (i < bit.len) {
        bit[i] += delta;
        i += i & -i;
    }
}

fn query(bit: []i32, idx: usize) i32 {
    var sum: i32 = 0;
    var i = idx;
    while (i > 0) {
        sum += bit[i];
        i -= i & -i;
    }
    return sum;
}

pub fn main() !void {
    var bit = [_]i32{0} ** 10;
    const arr = [_]i32{ 3, 2, -1, 6, 5, 4, -3, 3, 7, 2 };

    for (arr, 1..) |val, i| update(bit, i, val);

    std.debug.print("Sum 1-5: {}\n", .{query(bit, 5)});
    std.debug.print("Sum 1-10: {}\n", .{query(bit, 10)});
}

